    local function build(records,defaults,references,parentOrder)
        local nodes={}
        for _,record in ipairs(records) do nodes[record[1]]=Instance.new(record[2]) end
        local function apply(object,pairs)
            for i=1,#pairs,2 do
                local property=properties[pairs[i]]
                local ok,err=pcall(function() object[property]=values[pairs[i+1]] end)
                if not ok then skipped[property]=tostring(err) end
            end
        end
        for _,record in ipairs(records) do
            local object=nodes[record[1]]
            apply(object,defaults[record[2]] or {});apply(object,record[4])
        end
        for _,ref in ipairs(references) do
            local ok,err=pcall(function() nodes[ref[1]][properties[ref[2]]]=nodes[ref[3]] end)
            if not ok then skipped[properties[ref[2]]]=tostring(err) end
        end
        for _,link in ipairs(parentOrder) do nodes[link[1]].Parent=nodes[link[2]] end
        return nodes
    end
