--!nocheck
local RecorderFactory={}
function RecorderFactory.create(dependencies)
    local Portrait=assert(dependencies.Portrait,"Recorder: missing Portrait")
    --!nocheck
    -- Pure recorder state/validation; runtime dependencies are injected.
    local Recorder = {}
    local MAX_ENTRIES, MAX_DURATION = 2000, 86400
    local function finite(n)
        return type(n) == "number" and n == n and math.abs(n) < math.huge
    end
    local function array(t, maximum)
        assert(type(t) == "table", "Expected array")
        local count = 0
        for k in pairs(t) do
            assert(finite(k) and k >= 1 and k % 1 == 0 and k <= maximum, "Invalid array index")
            count = count + 1
        end
        for i = 1, count do assert(t[i] ~= nil, "Sparse array") end
        return count
    end
    local function validateCFrame(c)
        assert(array(c, 12) == 12, "CFrame needs 12 numbers")
        for i = 1, 12 do
            assert(finite(c[i]) and math.abs(c[i]) <= (i <= 3 and 1e7 or 1.001), "Invalid CFrame number")
        end
        for row = 0, 2 do
            local i = 4 + row * 3
            assert(math.abs(c[i]^2 + c[i+1]^2 + c[i+2]^2 - 1) < 0.002, "Invalid rotation")
            for other = row + 1, 2 do
                local j = 4 + other * 3
                assert(math.abs(c[i]*c[j]+c[i+1]*c[j+1]+c[i+2]*c[j+2]) < 0.002, "Invalid rotation")
            end
        end
        local det = c[4]*(c[8]*c[12]-c[9]*c[11]) - c[5]*(c[7]*c[12]-c[9]*c[10]) + c[6]*(c[7]*c[11]-c[8]*c[10])
        assert(math.abs(det-1) < 0.003, "Invalid rotation determinant")
    end
    function Recorder.validate(doc, placeId, userId, gameId)
        assert(type(doc) == "table" and doc.format == "AAPlacementRecorder" and (doc.version == 1 or doc.version == 2 or doc.version == 3), "Unsupported macro format")
        assert(finite(doc.placeId) and doc.placeId>0 and doc.placeId%1==0,"Invalid recorded PlaceId")
        if doc.gameId~=nil then assert(finite(doc.gameId) and doc.gameId>0 and doc.gameId%1==0,"Invalid recorded GameId") end
        if gameId and doc.gameId then assert(doc.gameId==gameId,"Macro belongs to another game") end
        assert(doc.placeId==placeId or (gameId and doc.gameId==gameId),"Macro place compatibility has not been verified")
        assert(doc.userId == userId, "Macro belongs to another account")
        local count = array(doc.entries, MAX_ENTRIES)
        local clean, previous, sold, levels = {}, 0, {}, {}
        for i = 1, count do
