--!nocheck
-- Injected state machine. No game-specific API calls in this module.
local Upgrader={}
function Upgrader.new(d)
    local self={alive=true,rows={},generation=0,cursor=0}
    local function validNumber(v) return type(v)=="number" and v==v and v>=0 and v<10000 and v%1==0 end
    local function sameUnit(row)
        if not d.valid(row.unit) then row.enabled=false;row.status="REMOVED / REPLACED";d.changed(row);return false end
        if d.identity then
            local identity=d.identity(row.unit)
            if identity==nil then row.status="WAIT UNIT IDENTITY";d.changed(row);return false end
            if row.identity==nil then row.identity=identity
            elseif identity~=row.identity then row.enabled=false;row.status="REMOVED / REPLACED";d.changed(row);return false end
        end
        return true
    end
    function self:add(unit)
        if not self.rows[unit] then self.rows[unit]={unit=unit,identity=d.identity and d.identity(unit),enabled=false,target=0,status="OFF",nextAttempt=0} end
        return self.rows[unit]
    end
    function self:enable(unit,on)
        local row=self:add(unit)
        assert(d.valid(unit),"Unit no longer exists")
        local level,maximum=d.levels(unit)
        row.enabled=on; row.blocked=nil; row.status=on and "QUEUED" or "OFF"
        if on and (not validNumber(level) or not validNumber(maximum) or level>maximum) then row.status="WAIT UNIT STATS" end
        d.changed(row)
    end
    function self:target(unit,value)
        local row=self:add(unit)
        assert(value=="max" or validNumber(value),"Invalid target upgrade")
        row.target=value
        d.changed(row)
    end
    function self:stop()
        self.generation=self.generation+1
        for _,row in pairs(self.rows) do row.enabled=false;row.status="STOPPED";d.changed(row) end
    end
    function self:destroy() self:stop();self.alive=false end
    function self:step(row)
        if not self.alive or not row.enabled or row.blocked then return end
        if not sameUnit(row) then return end
        local current,maximum=d.levels(row.unit)
        if not validNumber(current) or not validNumber(maximum) or current>maximum then
            row.status="WAIT UNIT STATS";d.changed(row);return
        end
        local target=row.target=="max" and maximum or math.min(row.target,maximum)
        if current>=target then row.enabled=false;row.status="DONE";d.changed(row);return end
        if row.awaitLevel then
            if row.lastCall and row.lastCall.done and not row.lastCall.values[1] then
                row.blocked=true;row.enabled=false;row.status="ERROR: late invocation failure";d.changed(row);return
            elseif row.lastCall and row.lastCall.done and row.lastCall.values[1] and row.lastCall.values[2]==false then row.awaitLevel=nil
            elseif current>row.awaitLevel then row.awaitLevel=nil;row.status="LEVEL CONFIRMED"
            elseif row.lastCall and row.lastCall.done and d.clock()>=row.nextAttempt then
                row.awaitLevel=nil;row.status="RECHECK / RETRY"
            else row.status="WAIT LEVEL REPLICATION";return end
        end
        if d.broker.pending or not d.canRun() or d.clock()<row.nextAttempt then return end
        local remote=d.remote()
        if not remote then row.status="WAIT REMOTE";return end
        local call={done=false}
        row.lastCall=call;row.awaitLevel=current
        local generation=self.generation
        d.broker.pending=call
        row.status="UPGRADING";d.changed(row)
        d.spawn(function()
            call.values=table.pack(pcall(d.invoke,remote,row.unit))
            call.done=true
            if d.broker.pending==call then d.broker.pending=nil end
        end)
        local started=d.clock()
        while not call.done do
            if not self.alive or self.generation~=generation or not row.enabled then return end
            if d.clock()-started>=15 and row.status~="WAIT SERVER" then row.status="WAIT SERVER";d.changed(row) end
            d.wait(0.05)
        end
        if not self.alive or self.generation~=generation or not row.enabled then return end
        if not sameUnit(row) then return end
        if not call.values[1] then
            row.blocked=true;row.enabled=false;row.status="ERROR: "..tostring(call.values[2]):sub(1,160);d.changed(row);return
        end
        -- Replicated level, not a generic successful pcall, confirms the effect.
        local deadline=d.clock()+2
        local after=d.levels(row.unit)
        while after==current and d.clock()<deadline do
            if not self.alive or self.generation~=generation or not row.enabled or not d.valid(row.unit) then return end
            d.wait(0.05);after=d.levels(row.unit)
        end
        if type(after)=="number" and after>current then
            row.awaitLevel=nil
            row.status="LEVEL "..after
            row.nextAttempt=d.clock()+1
        elseif call.values[2]==false then
            row.awaitLevel=nil
            row.status="WAIT / RETRY IN 2s"
            row.nextAttempt=d.clock()+2
