modules.Catalog=(function()
--!nocheck
-- Targeted read-only lookup: requested inventory UUID -> unit definition -> display data.
-- Does not require arbitrary modules, call game remotes, mutate scanned tables, or export them.
local Catalog={}
local function normal(id) return type(id)=="string" and id:lower():gsub("[{}]","") or nil end
local function first(t,keys)
    for _,key in ipairs(keys) do local v=rawget(t,key);if v~=nil then return v end end
end
local function friendly(v)
    return type(v)=="string" and #v>0 and #v<=120 and not v:find("[%c_{}]") and not v:match("^Unit #%d+$")
end
local function unitType(t,guid)
    if type(t)~="table" then return nil end
    for _,key in ipairs({"unit_id","unitId","unit_type","unitType","unit","id","modelName"}) do
