        for _,key in ipairs({"image","image_id","imageId","thumbnail","icon","portrait"}) do
            local v=rawget(def,key)
            if type(v)=="number" and v>0 and v%1==0 then v="rbxassetid://"..v end
            v=d.asset(v);if v~="" then icon=v;break end
        end
        local entry=result[inventoryId] or {}
        if name then
            entry.names=entry.names or {};entry.names[name]=true
            local count=0;for _ in pairs(entry.names) do count=count+1 end
            entry.displayName=count==1 and name or nil
        end
        if icon then
            entry.icons=entry.icons or {};entry.icons[icon]=true
            local count=0;for _ in pairs(entry.icons) do count=count+1 end
