            if self.queued then self.cancelRequested=true end
            if self.enabled then self.generation+=1;self.stage="idle";self.enabled=false;self.configKey=nil end
            return
        end
        if not self.enabled then self.enabled=true;self.stage="idle";self.generation+=1;self.configKey=nil end
        if not d.alive() then return end
        local allowed,reason,config,retry=d.configuration()
        config=config or {friends=false,match=false}
        if not allowed then
            if retry then
                if self.stage~="idle" then self.generation+=1 end
                self.stage="idle";self.configKey=nil;self.nextAttempt=d.clock()+2
            else self.stage="blocked" end
            d.report(reason);return
        end
        local levelId=config.levelId or (config.match and "namek_infinite" or "namek_level_1")
        local exists=d.levelExists and d.levelExists(levelId) or not d.levelExists and (levelId=="namek_level_1" or levelId=="namek_infinite")
