            elseif action=="tower" then result=table.pack(pcall(d.invoke,remote,config.room,difficulty))
            elseif action=="lock" then result=table.pack(pcall(d.invoke,remote,lobby,levelId,config.friends==true,difficulty))
            else result=table.pack(pcall(d.invoke,remote,lobby)) end
