    local player=assert(context.player,"MainSettingsController: missing player")
    local nodes=assert(context.nodes,"MainSettingsController: missing nodes")
    local prefix=assert(context.prefix,"MainSettingsController: missing prefix")
    local readJSON=assert(context.readJSON,"MainSettingsController: missing readJSON")
