        if type(saved)=="string" and #saved<=120 then nodes[pair[2]].Text=saved end
    end
    normalizeRaid()
    local function pendingMain(ref)
        if ref==580 or ref==567 or ref==593 then nodes[632].Text="Story Auto Join updated";return end
        if ref==660 or ref==673 then nodes[632].Text="Legend Auto Join / Find Match updated";return end
        if lobbyModeSet[ref] then nodes[632].Text="Main auto mode updated";return end
        if ref==882 or ref==895 then
            nodes[632].Text="Auto Start / Skip configured"
