    for _,ref in ipairs(numericBoxes) do
        local box=nodes[ref];local key=tostring(ref);local initial=box.Text
        local integer=ref==748 or ref==1081 or ref==1102 or ref==1123
        local minimum=integer and 1 or 0
        local function valid(value)
