        local value=button:FindFirstChildWhichIsA("TextLabel",true)
        if not value then
            for _,child in ipairs(button.Parent:GetChildren()) do
                if child:IsA("TextLabel") and child~=label then value=child end
            end
        end
        if value then
            local key=tostring(ref)
            if type(mainState.values[key])=="string" and #mainState.values[key]<=120 then value.Text=mainState.values[key] end
            local function currentChoices()
                if ref==545 then return StoryCatalog.worlds() end
                if ref==552 then return StoryCatalog.acts(nodes[548].Text) end
                if ref==559 then return StoryCatalog.difficulties(nodes[548].Text,nodes[555].Text) end
                if ref==645 then return LegendCatalog.worlds() end
                if ref==652 then return LegendCatalog.acts(nodes[648].Text) end
                if ref==695 then return RaidCatalog.worlds() end
                if ref==702 then return RaidCatalog.acts(nodes[698].Text) end
                if ref==751 then return world.hardLocked() and {"Normal"} or {"Normal","Hard"} end
                if ref==815 then
                    local choices=world.rewards()
                    if value.Text~="" and not table.find(choices,value.Text) then choices[#choices+1]=value.Text end
                    return choices
