            end
            local choices=currentChoices()
            if choices and not table.find(choices,value.Text) then
                value.Text=choices[1];mainState.values[key]=value.Text
            end
            bind(button,function()
                local choices=currentChoices()
                if choices then
                    local options={}
                    for _,choice in ipairs(choices) do
                        options[#options+1]={label=choice,selected=value.Text==choice,run=function()
                            value.Text=choice;mainState.values[key]=choice
                            if ref==545 then
                                nodes[555].Text=StoryCatalog.acts(choice)[1];nodes[562].Text="Normal"
                            elseif ref==552 then
                                local difficulty=choice=="Infinite" and "Hard" or "Normal"
                                nodes[562].Text=difficulty;mainState.values["559"]=difficulty
                            end
                            if ref==545 or ref==552 or ref==559 then normalizeStory() end
                            if ref==645 then nodes[655].Text=LegendCatalog.acts(choice)[1] end
                            if ref==645 or ref==652 then normalizeLegend() end
                            if ref==695 then nodes[705].Text=RaidCatalog.acts(choice)[1] end
                            if ref==695 or ref==702 then normalizeRaid() end
                            saveMain()
                        end}
                    end
                    dropdown(button,options)
