                local editor=Instance.new("TextBox");editor.Name="MainValueEditor"
                editor.Size=UDim2.fromScale(1,1);editor.BackgroundColor3=Color3.fromRGB(28,28,41)
                editor.TextColor3=value.TextColor3;editor.Font=value.Font;editor.TextSize=value.TextSize
