    local function isHelpButton(node)
        for _,child in ipairs(node.Parent:GetChildren()) do
            if child:IsA("TextLabel") and child.Text:lower()=="how it works" then return true end
        end
        return false
    end
    for ref,node in pairs(nodes) do
        if node:IsA("TextButton") and node:IsDescendantOf(nodes[528]) and not selectorSet[ref] and ref~=1013 and not isHelpButton(node) then
            local track
