-- Module: src/features/main/ActionsController.lua
modules.MainActionsController=(function()
--!nocheck
-- Dependencies are explicit; this module does not install hooks on import.
local MainActionsController={}
function MainActionsController.mount(context)
    local runtime=assert(context.runtime,"MainActionsController: missing runtime")
    local mainState=assert(context.mainState,"MainActionsController: missing mainState")
    local broker=assert(context.broker,"MainActionsController: missing broker")
    local nodes=assert(context.nodes,"MainActionsController: missing nodes")
    local player=assert(context.player,"MainActionsController: missing player")
    local RS=assert(context.RS,"MainActionsController: missing RS")
    local MatchActions=assert(context.MatchActions,"MainActionsController: missing MatchActions")
    local StoryActions=assert(context.StoryActions,"MainActionsController: missing StoryActions")
    local StoryCatalog=assert(context.StoryCatalog,"MainActionsController: missing StoryCatalog")
    local LegendCatalog=assert(context.LegendCatalog,"MainActionsController: missing LegendCatalog")
    local matchActions=MatchActions.new({
        broker=broker,clock=os.clock,spawn=task.spawn,
        alive=function() return runtime.alive end,
        enabled=function(kind) return mainState.values[kind=="start" and "882" or "895"]==true end,
        state=function()
            local started=workspace:FindFirstChild("_waves_started")
            local wave=workspace:FindFirstChild("_wave_num")
            return started and started.Value,wave and wave.Value
        end,
        visible=function(name)
            local root=player:FindFirstChild("PlayerGui")
            local screen=root and root:FindFirstChild(name)
            local holder=screen and screen:FindFirstChild("Holder")
            return screen and screen:IsA("ScreenGui") and screen.Enabled and holder and holder.Visible
        end,
        remote=function(name)
            local endpoints=RS:FindFirstChild("endpoints")
            local folder=endpoints and endpoints:FindFirstChild("client_to_server")
            local remote=folder and folder:FindFirstChild(name)
            return remote and remote:IsA("RemoteFunction") and remote or nil
        end,
        invoke=function(remote) return remote:InvokeServer() end,
        report=function(message) nodes[632].Text=message end,
    })
    runtime.matchActions=matchActions
    nodes[632].Text="Auto Start / Skip ready"
    task.spawn(function()
        while runtime.alive do
            local ok,err=pcall(function() matchActions:tick() end)
            if not ok then nodes[632].Text="Match: "..tostring(err):sub(1,100) end
            task.wait(0.4)
        end
    end)

    local world=assert(context.world,"MainActionsController: missing world reader")
    local Modes=assert(context.MainModes,"MainActionsController: missing MainModes")
    local RaidCatalog=assert(context.RaidCatalog,"MainActionsController: missing RaidCatalog")
    local function configuration()
        local config,reason,retry=Modes.resolve({values=mainState.values,nodes=nodes,world=world,
            StoryCatalog=StoryCatalog,LegendCatalog=LegendCatalog,RaidCatalog=RaidCatalog,save=runtime.saveMainSettings})
        return config~=nil,reason,config,retry
    end
    local actions=StoryActions.new({
        broker=broker,clock=os.clock,spawn=task.spawn,
        alive=function() return runtime.alive end,
        enabled=function() return Modes.active(mainState.values)~=nil end,
        configuration=configuration,
        levelExists=function(id)
            if StoryCatalog.exists(id) or LegendCatalog.exists(id) or RaidCatalog.exists(id) then return true end
            if id=="__NORMAL_CHALLENGE" or id=="__DAILY_CHALLENGE" then return true end
            local room,difficulty=id:match("^__INFINITE_TOWER:(%d+):(%a+)$")
            return room and tonumber(room)>=1 and tonumber(room)<=1000000 and (difficulty=="Normal" or difficulty=="Hard") or false
        end,
        readyMatch=function()
            if not world.lobbyServer() then return false,"Waiting for the lobby server" end
            local joined=world.inLobby()
            if joined==nil then return false,"Lobby membership has not loaded" end
            return joined==false,"Waiting to leave the current lobby"
        end,
        ownedLobby=world.owned,candidate=world.candidate,
        exists=function(name) return world.find(name)~=nil end,
        validConfiguration=function(config,lobby)
            return world.valid(config,config.match and config.sourceLobby or lobby)
        end,
        remote=function(name)
