--!nocheck
local ToggleAnimator={}
function ToggleAnimator.mount(context)
    local entranceMotion=assert(context.entranceMotion,"ToggleAnimator: missing entranceMotion")
    local switchTweens,switchGoals={},{}
    local function switchVisual(object,property,goal,animated)
        if not object then return end
        local previous=switchGoals[object] or {}
        if previous[property]==goal then return end
        previous[property]=goal;switchGoals[object]=previous
        local active=switchTweens[object] or {};switchTweens[object]=active
        if active[property] then active[property]:Cancel();active[property]:Destroy();active[property]=nil end
        local reduced=false
        pcall(function() reduced=game:GetService("GuiService").ReducedMotionEnabled end)
        if not animated or reduced then object[property]=goal;return end
        entranceMotion:cancel()
        local tween=game:GetService("TweenService"):Create(object,
            TweenInfo.new(0.2,Enum.EasingStyle.Quart,Enum.EasingDirection.Out),{[property]=goal})
        active[property]=tween;tween:Play()
    end

    local function destroy()
        for _,properties in pairs(switchTweens) do
            for _,tween in pairs(properties) do tween:Cancel();tween:Destroy() end
        end
        table.clear(switchTweens);table.clear(switchGoals)
    end

    return {set=switchVisual,destroy=destroy,active=switchTweens,goals=switchGoals}
end
return ToggleAnimator

end)()
-- Program: src/infrastructure/Autoexec.lua
modules.BootstrapProgram=[====[
--!nocheck
-- Portable autoexec/teleport entry. Executor file APIs resolve their own workspace.
-- No Windows account name or installation directory is embedded here.
local function start()
    if type(readfile)~="function" or type(isfile)~="function" or type(loadstring)~="function" then return end
    if not game:IsLoaded() then game.Loaded:Wait() end
    local Players=game:GetService("Players")
    local Http=game:GetService("HttpService")
    local player=Players.LocalPlayer
    local deadline=os.clock()+30
    while not player and os.clock()<deadline do task.wait(0.1);player=Players.LocalPlayer end
    if not player then return end
    local settingsPath="GH_AA_"..player.UserId.."_settings.json"
    local function enabled()
        local ok,doc=pcall(function()
            if not isfile(settingsPath) then return nil end
            return Http:JSONDecode(readfile(settingsPath))
        end)
        if ok and type(doc)=="table" and doc.format=="GHAAUISettings" and doc.version==1
            and type(doc.settings)=="table" and doc.settings.autoLoad==true
            and type(doc.gameId)=="number" and doc.gameId>0 and game.GameId==doc.gameId then return true end
        local autoOk,auto=pcall(function()
            local path="GH_AA_"..player.UserId.."_autoplay.json"
            if not isfile(path) then return nil end
            return Http:JSONDecode(readfile(path))
        end)
        -- Auto Play itself authorizes relaunch across teleports, scoped to this account/game.
        return autoOk and type(auto)=="table" and auto.format=="GHAAUIAutoPlay" and auto.version==1
            and auto.enabled==true and auto.userId==player.UserId and auto.gameId==game.GameId
            and type(auto.gameId)=="number" and auto.gameId>0
            and type(auto.name)=="string" and #auto.name>0 and #auto.name<=48 and not auto.name:find("[%c/\\]") or false
    end
    if not enabled() then return end
    local env=type(getgenv)=="function" and getgenv() or _G
    if (env.__GHAAUI_V2 and env.__GHAAUI_V2.alive) or env.__GHAAUI_Booting then return end
    env.__GHAAUI_Booting=true
    local ok,err=pcall(function()
        local cachePath="GH_AAUI_runtime.lua"
        local cached
        if isfile(cachePath) then
            local readOk,value=pcall(readfile,cachePath)
            if readOk and type(value)=="string" and #value<=4*1024*1024 then cached=value end
        end
        local remote
        local fetchOk,value=pcall(function()
            return game:HttpGet("https://raw.githubusercontent.com/luvmikari/gh-hub/main/main.lua")
        end)
        if fetchOk and type(value)=="string" and #value<=4*1024*1024 then remote=value end
        local function version(source)
            if not source then return nil end
            local major,minor=source:match('local version%s*=%s*"(%d+)%.(%d+)"')
            return major and (tonumber(major)*100000+tonumber(minor)) or nil
        end
        local cachedVersion,remoteVersion=version(cached),version(remote)
        local preferred=remoteVersion and (not cachedVersion or remoteVersion>=cachedVersion) and remote or cached
        local fallback=preferred==remote and cached or remote
        local compiled,compileError
        if preferred then compiled,compileError=loadstring(preferred) end
        if not compiled and fallback and fallback~=preferred then
            compiled,compileError=loadstring(fallback);preferred=fallback
        end
        assert(compiled,"GH AAUI autoload: no runnable download/cache. Update main.lua or install GH_AAUI_runtime.lua. "..tostring(compileError or ""))
        if not enabled() then return end
        if type(writefile)=="function" then pcall(writefile,cachePath,preferred) end
        compiled()
    end)
    env.__GHAAUI_Booting=nil
    if not ok then warn("[GH autoload] "..tostring(err)) end
end
start()

]====]
