modules.AutoLoader=(function()
--!nocheck
-- The same portable program is used by autoexec and queue_on_teleport.
local AutoLoader={}
function AutoLoader.new(d)
    local self={queued=false}
    function self:prepare()
        assert(type(d.read)=="function" and type(d.write)=="function" and type(d.isfile)=="function",
            "Autoload requires executor file APIs")
        d.write("GH_AAUI_Autoexec.lua",d.program)
        assert(d.read("GH_AAUI_Autoexec.lua")==d.program,"Autoload entry write verification failed")
    end
    function self:onTeleport(started,failed,enabled)
        if failed then self.queued=false;return false end
        if not started or not enabled or self.queued then return false end
        if type(d.queue)~="function" then return false,"Teleport autoload unavailable: executor has no queue_on_teleport" end
        d.queue(d.program)
        self.queued=true
        return true
    end
    return self
end
return AutoLoader

end)()
