modules.PlaceScope=(function()
--!nocheck
-- Positive membership is resolved through the current experience's documented place list.
local PlaceScope={}
function PlaceScope.new(d)
    local self={known={[d.placeId]=d.gameId},loaded=false,loading=false,retryAt=0}
    function self:resolve(placeId)
        if self.known[placeId] then return self.known[placeId] end
        if self.loaded then return nil,"Recorded place is not in the current experience's place list" end
        if self.loading then return nil,"Place compatibility check is already running" end
        if d.clock()<self.retryAt then return nil,"Place lookup unavailable; retry shortly" end
        self.loading=true
        local ok,err=pcall(function()
            local pages=d.places()
            local count=0
            while true do
                count+=1;assert(count<=100,"Place list exceeded lookup limit")
                if d.alive and not d.alive() then error("Application unloaded during place lookup") end
                for _,place in ipairs(pages:GetCurrentPage()) do
                    local id=tonumber(place.PlaceId)
                    if id and id>0 and id%1==0 then self.known[id]=d.gameId end
                end
                if self.known[placeId] then return end
                if pages.IsFinished then self.loaded=true;return end
                pages:AdvanceToNextPageAsync()
            end
        end)
        self.loading=false
        if not ok then self.retryAt=d.clock()+5;return nil,tostring(err) end
        return self.known[placeId],self.known[placeId] and nil or "Recorded place is not in this game's place list"
    end
    return self
end
return PlaceScope

end)()
