-- Module: src/features/macros/Actions.lua
modules.MacroActions=(function()
--!nocheck
-- Runtime adapter. The namecall hook only copies Lua state; engine reads happen here.
local Actions={}
function Actions.new(d)
    local self={alive=true,queue={},head=1,recordUnits={},recordLevels={},bindings={},claimed={},cached={},remoteKinds={}}
    local core=d.core
    local function active(generation) return self.alive and core.alive and core.generation==generation end
    local function snapshot()
        local set={};for _,unit in ipairs(d.models()) do set[unit]=true end;return set
    end
    function self:refresh()
        local cached={}
        for _,unit in ipairs(d.models()) do cached[unit]={level=d.level(unit)} end
        self.cached=cached
    end
    function self:startRecord()
        self.queue={};self.head=1;self.recordUnits={};self.recordLevels={};self.claimed={}
        self:refresh();self.remoteKinds={}
        for _,kind in ipairs({"place","upgrade","sell"}) do
            local remote=d.remote(kind);if remote then self.remoteKinds[remote]=kind end
        end
    end
    function self:startPlay() self.bindings={};self.claimed={} end
    -- Called inside the hook: no Instance methods, properties, or yielding.
    function self:begin(remote,args)
        if not self.alive or core.mode~="REC" then return end
        local kind=self.remoteKinds[remote];if not kind then return end
        local before={};for unit in pairs(self.cached) do before[unit]=true end
        local cached=self.cached[args[1]]
        local ticket={kind=kind,args=args,before=before,level=cached and cached.level,
            token=core.recordToken,time=d.clock()-core.started,queue=self.queue}
        self.queue[#self.queue+1]=ticket
        return ticket
    end
    local function recording(ticket)
        return self.alive and core.mode=="REC" and core.recordToken==ticket.token and self.queue==ticket.queue
    end
    local function findPlacement(entry,before,alive,timeout)
        local deadline=d.clock()+timeout
        repeat
            if not alive() then return end
            local unit=d.Plan.candidate(entry,d.models(),before,self.claimed,d.position,function() return true end)
            if unit then return unit end
            d.wait(0.1)
        until d.clock()>=deadline
    end
    function self:commit(ticket)
        if not recording(ticket) then return end
        assert(ticket.result[1],"Recorded request failed with an unknown outcome; recording stopped")
        local args,result=ticket.args,ticket.result
        local reply={n=result.n-1};for i=2,result.n do reply[i-1]=result[i] end
        local outcome=d.Recorder.response(reply)
        if outcome=="retry" then return end
        local kind=ticket.kind
        if kind=="place" then
            assert(args.n==2 and type(args[1])=="string","Placement call schema changed")
            assert(d.isCFrame(args[2]),"Placement CFrame unavailable")
            if outcome~="accepted" then d.report("Placement not recorded: server success was not confirmed");return end
            local cf=d.components(args[2]);d.Recorder.validateCFrame(cf)
            local entry={id=args[1],cframe=cf}
            local unit=findPlacement(entry,ticket.before,function() return recording(ticket) end,12)
            if not recording(ticket) then return end
            assert(unit,"Cannot bind recorded placement uniquely; recording stopped")
            local slot=core:captureAction("place",nil,args[1],cf,nil,ticket.time)
            self.recordUnits[unit]=slot;self.recordLevels[unit]=0;self.claimed[unit]=true
            self:refresh()
            return
        end
        assert(args.n==1,"Unit action argument schema changed")
        local unit=args[1];local slot=self.recordUnits[unit]
        if not slot then d.report("Skipped "..kind..": place this unit during the current recording first");return end
        local placement=core.entries[slot]
        if kind=="upgrade" then
            local current=d.level(unit)
            -- Known success is true. An empty no-money reply must never create an action.
            if outcome~="accepted" then return end
            local deadline=d.clock()+8
            while recording(ticket) and d.valid(unit) and (not current or current<=self.recordLevels[unit]) and d.clock()<deadline do
                d.wait(0.1);current=d.level(unit)
            end
            if not recording(ticket) then return end
            assert(current and current>self.recordLevels[unit],"Upgrade success could not be confirmed from unit level")
            local level=self.recordLevels[unit]+1
            core:captureAction("upgrade",slot,placement.id,placement.cframe,level,ticket.time)
            self.recordLevels[unit]=level
        else
            local deadline=d.clock()+8
            while recording(ticket) and d.valid(unit) and d.clock()<deadline do d.wait(0.1) end
            if not recording(ticket) then return end
            if d.valid(unit) then d.report("Sale not recorded: unit removal was not confirmed");return end
            core:captureAction("sell",slot,placement.id,placement.cframe,nil,ticket.time)
            self.recordUnits[unit]=nil
        end
    end
    function self:finish(ticket,result)
        if not recording(ticket) then return end
        ticket.result=result
        if self.draining then return end
        self.draining=true
        d.spawn(function()
            local queue=ticket.queue
            while self.alive and self.queue==queue do
                local nextTicket=queue[self.head]
                if not nextTicket then break end
                if not recording(nextTicket) then break end
                if not nextTicket.result then d.wait(0.05) else
                    local ok,err=pcall(self.commit,self,nextTicket)
                    self.head+=1
                    if not ok then core:stop();d.report(tostring(err));break end
                end
            end
            self.draining=false
            -- A fresh recording can replace a queue while an older worker is yielding.
            local nextTicket=self.queue[self.head]
            if nextTicket and nextTicket.result and recording(nextTicket) then self:finish(nextTicket,nextTicket.result) end
        end)
    end
    function self:beforePlacement() return {before=snapshot()} end
    function self:placed(entry,index,generation,context)
        local unit=findPlacement(entry,context.before,function() return active(generation) end,30)
        if not active(generation) then return end
        assert(unit,"Placed unit was not uniquely identified; playback stopped")
        self.claimed[unit]=true
        self.bindings[entry.slot or index]={unit=unit,identity=d.identity(unit)}
    end
    function self:invoke(remote,entry,index,context,generation)
        assert(active(generation),"Playback stopped")
        local binding=assert(self.bindings[entry.slot],"Recorded placement is not bound")
        local unit=binding.unit
        if entry.action=="sell" and context.saleSent and not d.valid(unit) then return true end
        assert(d.valid(unit),"Recorded unit is no longer in this match")
        local identity=d.identity(unit)
        assert(not binding.identity or identity==binding.identity,"Recorded unit identity changed")
        if not binding.identity then binding.identity=identity end
        if entry.action=="upgrade" then
            local current=d.level(unit)
            if current==nil then return false end
            if current>=entry.level then return true end
        end
        -- Exactly one model argument; never resolve a sale by unit name alone.
        local returned=table.pack(d.invoke(remote,unit))
        if not active(generation) then return false end
        local outcome=d.Recorder.response(returned)
        if outcome=="retry" then return false end
        if entry.action=="sell" then context.saleSent=true end
        if entry.action=="upgrade" and outcome~="accepted" then
            local current=d.level(unit);return current~=nil and current>=entry.level
        end
        local deadline=d.clock()+8
        repeat
            if not active(generation) then return false end
            if entry.action=="sell" then if not d.valid(unit) then return true end
            else
                local current=d.level(unit)
                if current and current>=entry.level then return true end
            end
            d.wait(0.1)
        until d.clock()>=deadline
        return false
    end
    function self:destroy() self.alive=false;self.queue={};self.bindings={} end
    return self
end
return Actions

end)()
