}
local byName,byId={},{}
for _,world in ipairs(worlds) do
    byName[world.label]=world
    byName[world.key]=world
    for _,level in ipairs(world.levels) do byId[level.id]=level end
end
function Catalog.worlds()
    local out={};for _,world in ipairs(worlds) do out[#out+1]=world.label end;return out
end
function Catalog.acts(name)
    local world=byName[name];local out={}
    if world then for _,level in ipairs(world.levels) do out[#out+1]=level.label end end
    return out
end
function Catalog.level(name,act)
    local world=byName[name]
    if world then for _,level in ipairs(world.levels) do if level.label==act then return level end end end
end
function Catalog.difficulties(name,act)
    local level=Catalog.level(name,act)
    if not level then return {} end
    return level.infinite and {"Hard"} or {"Normal","Hard","Insane"}
end
function Catalog.exists(id) return byId[id]~=nil end
function Catalog.configuration(name,act,difficulty)
    local level=Catalog.level(name,act)
    if not level then return nil,"Choose a valid map and act" end
    local choices=Catalog.difficulties(name,act)
    if level.infinite then difficulty="Hard" end
    if not table.find(choices,difficulty) then return nil,"Choose a supported difficulty" end
    return {levelId=level.id,infinite=level.infinite,difficulty=difficulty}
end
return Catalog

end)()
-- Module: src/ui/HelpSections.lua
modules.HelpSections=(function()
--!nocheck
-- Local disclosure state, independent of feature toggles and saved game settings.
local HelpSections={}
function HelpSections.mount(context)
    local sections={}
    for _,title in ipairs(context.gui:GetDescendants()) do
        if title:IsA("TextLabel") and title.Text:lower()=="how it works" then
            local header=title.Parent
            local button=header:FindFirstChildWhichIsA("TextButton")
            local bodies,arrow,hint={}
            for _,child in ipairs(header:GetChildren()) do
                if child:IsA("ImageLabel") and child.Position.X.Scale>=0.5 then arrow=child end
                if child:IsA("TextLabel") and child~=title then hint=child end
            end
            for _,child in ipairs(header.Parent:GetChildren()) do
                if child:IsA("TextLabel") and child.LayoutOrder>header.LayoutOrder then bodies[#bodies+1]=child end
            end
            if button and #bodies>0 then
                header:SetAttribute("HowItWorksHeader",true)
                button:SetAttribute("HelpDisclosure",true)
                button.Position=UDim2.new(1,-32,0,0);button.Size=UDim2.new(0,32,1,0)
                button.AnchorPoint=Vector2.new(0,0);button.BackgroundTransparency=1;button.Text=""
                button.AutoButtonColor=false;button.Active=true;button.Interactable=true
                button.ZIndex=math.max(title.ZIndex,arrow and arrow.ZIndex or 1,button.ZIndex)+1
                local expanded=false
                local function draw()
                    header:SetAttribute("Expanded",expanded)
                    for _,body in ipairs(bodies) do body.Visible=expanded end
                    if arrow then arrow.Rotation=expanded and 180 or 0 end
                    if hint then hint.Visible=not expanded end
                end
                draw()
                context.bind(button,function() expanded=not expanded;draw() end)
                sections[#sections+1]={header=header,button=button,bodies=bodies,arrow=arrow}
            end
        end
    end
    return sections
end
return HelpSections

end)()
