    {label="Virtual Dungeon (Bosses)",key="sao_legend",acts={{label="Act 1",id="sao_legend_1",matchmaking=true},{label="Act 2",id="sao_legend_2",matchmaking=true},{label="Act 3",id="sao_legend_3",matchmaking=true}}},
}
local byName,byId={},{}
for _,world in ipairs(worlds) do
    byName[world.label]=world
    for _,act in ipairs(world.acts) do byId[act.id]=act end
end
function Catalog.worlds()
    local out={};for _,world in ipairs(worlds) do out[#out+1]=world.label end;return out
end
function Catalog.acts(name)
    local out={};local world=byName[name]
    if world then for _,act in ipairs(world.acts) do out[#out+1]=act.label end end
    return out
end
function Catalog.exists(id) return byId[id]~=nil end
function Catalog.configuration(name,label,match)
    local world=byName[name]
    if world then for _,act in ipairs(world.acts) do
        if act.label==label then
            if match and not act.matchmaking then return nil,"Find Match is not listed for this Legend stage" end
            return {levelId=act.id,difficulty="Hard",friends=false,match=match==true,leaveBeforeMatch=match==true}
        end
    end end
    return nil,"Choose a valid Legend stage and act"
end
return Catalog

end)()
