-- Module: src/features/main/WorldState.lua
modules.WorldState=(function()
--!nocheck
-- Reads only the observed lobby/value/UI paths. Lobby numbers are never stored.
local WorldState={}
function WorldState.new(d)
 local self={}
 local function path(root,...)
  for _,name in ipairs({...}) do root=root and root:FindFirstChild(name) end;return root
 end
 local function value(root,name)
  local child=root and root:FindFirstChild(name)
  if child and child:IsA("ValueBase") then return child.Value end
 end
 function self.folder(mode)
  if mode=="story" or mode=="legend" then return path(d.workspace,"_LOBBIES","Story") end
  if mode=="raid" then return path(d.workspace,"_RAID","Raid") end
  if mode=="challenge" then return path(d.workspace,"_CHALLENGES","Challenges") end
  if mode=="daily" then return path(d.workspace,"_CHALLENGES","DailyChallenge") end
 end
 function self.inLobby() return value(d.player,"AlreadyInLobby") end
 function self.lobbyServer() return self.folder("story")~=nil end
 function self.find(name)
  for _,mode in ipairs({"story","raid","challenge","daily"}) do
   local root=self.folder(mode);local lobby=root and root:FindFirstChild(name)
   if lobby then return lobby end
  end
 end
 function self.owned(config)
  if self.inLobby()~=true then return end
  local modes=config and not config.match and {config.mode or "story"} or {"story","raid","challenge","daily"}
  local found
  for _,mode in ipairs(modes) do
   local root=self.folder(mode)
   if root then for _,lobby in ipairs(root:GetChildren()) do
    if value(lobby,"Owner")==d.player and value(lobby,"Teleporting")~=true then
     if found then return end;found=lobby.Name
    end
   end end
  end
  return found
 end
 function self.reward(lobby)
  local reward=value(lobby,"Reward")
  return type(reward)=="string" and reward~="" and #reward<=120 and reward or nil
 end
 function self.signature(lobby)
  return table.concat({tostring(value(lobby,"Level")),tostring(value(lobby,"Challenge")),tostring(value(lobby,"Reward"))},"|")
 end
 function self.candidate(config)
  local root=self.folder(config.mode or "story");if not root then return end
  local rows=root:GetChildren();table.sort(rows,function(a,b) return a.Name<b.Name end)
  for _,lobby in ipairs(rows) do
   local active=value(lobby,"Active");local level=value(lobby,"Level")
   local owned=value(lobby,"Owner")
   local available=(config.match==true or active==false and (owned==nil or owned==d.player)) and value(lobby,"Teleporting")~=true
   local validLevel=config.skipLock and type(level)=="string" and level~="" or not config.skipLock and level==""
   if available and validLevel and (not config.reward or self.reward(lobby)==config.reward) then
    if (not config.signature or self.signature(lobby)==config.signature) and (not config.lobby or config.lobby==lobby.Name) then return lobby.Name end
   end
  end
 end
 function self.rewards()
  local out={"None"};local seen={};local root=self.folder("challenge")
  if root then for _,lobby in ipairs(root:GetChildren()) do
   local reward=self.reward(lobby);if reward and not seen[reward] then out[#out+1]=reward;seen[reward]=true end
  end end
  table.sort(out,function(a,b) if a==b then return false elseif a=="None" then return true elseif b=="None" then return false else return a<b end end)
  return out
 end
 function self.lastRoom()
  local label=path(d.player,"PlayerGui","InfiniteTowerUI","InfiniteLeaderboard","Ranking","Wrapper","Frame","FurthestRoom","V")
  local n=label and label:IsA("TextLabel") and tonumber(label.Text)
  if type(n)=="number" and n==n and n>=1 and n%1==0 and n<=1000000 then return n end
 end
 function self.hardLocked()
  local hard=path(d.player,"PlayerGui","InfiniteTowerUI","LevelSelect","InfoFrame","Bottom","Difficulty","Items","Hard")
  local lock=hard and hard:FindFirstChild("Locked")
  return lock and lock:IsA("GuiObject") and lock.Visible==true or false
 end
