--!nocheck
-- One playback claim per observed match. Completion/STOP never re-arms that claim.
local AutoPlay={}
function AutoPlay.new(d)
    local self={enabled=false,used=false,epoch=0,busy=false,alive=true,active=false}
    local previousStarted,previousWave
    function self:reset()
        self.epoch+=1;self.used=false;self.active=false;self.readyAt=nil
        if self.busy or self.enabled and d.mode()=="PLAY" then d.stop() end
        -- A yielding compatibility check remains serialized until it returns.
    end
    function self:played() self.used=true end
    function self:suppress()
        self.epoch+=1;self.used=true
        if self.busy then d.stop() end
    end
    function self:set(enabled)
        self.enabled=enabled
        if not enabled then
            self.epoch+=1
            if self.busy then d.stop() end
        end
    end
    function self:tick()
        if not self.alive then return end
        local started,wave=d.state()
        if type(started)~="boolean" or type(wave)~="number" then return end
        local reset=previousStarted==true and started==false
            or previousWave and previousWave>0 and wave<previousWave and wave<=1
        if reset then self:reset() end
        previousStarted,previousWave=started,wave
        local active=started==true and wave>=1
        if active and not self.active then self.readyAt=d.clock()+0.75 end
        self.active=active
        if not self.enabled or not self.active or self.used or self.busy or d.clock()<(self.readyAt or math.huge) then return end
        -- Manual REC/PLAY is never replaced by the automatic launcher.
        if d.mode()=="PLAY" then self.used=true;return end
        if d.mode()~="IDLE" or not d.ready() then return end
        self.used=true;self.busy=true
        local epoch=self.epoch
        d.spawn(function()
            local ok,err=pcall(function()
                if not self.alive or not self.enabled or epoch~=self.epoch then return end
                d.play()
            end)
            self.busy=false
            if not ok and self.alive and epoch==self.epoch then d.report("Auto Play: "..tostring(err)) end
        end)
    end
    function self:destroy()
        self:set(false);self.alive=false
    end
    return self
end
