    local function save()
        d.writeJSON(file,{format="GHAAUIAutoPlay",version=1,userId=d.player.UserId,gameId=game.GameId,
            enabled=choice.enabled,name=choice.name})
    end
    local function draw(animated)
        d.n(130).Text=d.text("Auto Play Macro (new match)","Автозапуск макроса в новом матче")
        if d.baseTransparency[d.n(134)] then d.baseTransparency[d.n(134)].BackgroundTransparency=choice.enabled and 0 or 1 end
        d.switchVisual(d.n(134),"BackgroundTransparency",choice.enabled and (1-d.opacity()) or 1,animated)
        d.switchVisual(d.n(137),"Position",UDim2.new(0,choice.enabled and 26 or 10,0.5,0),animated)
        runtime.navigation.setFeature("Macro","AutoPlay",choice.enabled)
    end
    function engine:selectionChanged(name)
        choice.name=validName(name) and name or ""
        if choice.name=="" then choice.enabled=false;self:set(false) end
        save();draw(true)
    end
    function engine:refresh() draw(false) end
    runtime.autoPlay=engine
    runtime.autoPlayOptions=choice
    if choice.name~="" then
        local ok,err=pcall(function()
            d.restore(choice.name)
            assert(not choice.enabled or #core.entries>0,"Saved macro is empty")
        end)
        if not ok then
            choice.enabled=false
            pcall(save)
            d.report("Auto Play could not load the selected macro: "..tostring(err))
        end
    end
    engine:set(choice.enabled)
    draw(false)
    d.bind(d.n(129),function()
        if not choice.enabled then
            d.prepareMacro()
            assert(validName(d.selected()) and #core.entries>0,"Save and select a non-empty macro first")
            d.prepare()
            choice.name=d.selected()
        end
        local enabled=not choice.enabled
        -- Commit before changing actual state so failed storage never fakes a saved setting.
        local old=choice.enabled;choice.enabled=enabled
        local ok,err=pcall(save)
        if not ok then choice.enabled=old;error(err) end
        engine:set(enabled);draw(true)
        d.report(enabled and "Auto Play enabled; waiting for a new match" or "Auto Play disabled")
    end)
    local observed={}
    local function tick() engine:tick() end
    local function watch()
        for _,name in ipairs({"_waves_started","_wave_num"}) do
            local obj=workspace:FindFirstChild(name)
            if observed[name] and observed[name].object~=obj then observed[name].connection:Disconnect();observed[name]=nil end
            if obj and not observed[name] then
                observed[name]={object=obj,connection=d.connect(obj:GetPropertyChangedSignal("Value"),d.safe(tick))}
            end
        end
    end
    task.spawn(function()
        while runtime.alive do
            local ok,err=pcall(function() watch();tick() end)
            if not ok then d.report("Auto Play: "..tostring(err)) end
            task.wait(0.25)
        end
    end)
    local oldUnload=runtime.unload
    runtime.unload=function() engine:destroy();oldUnload() end
    return engine
end
return Controller

