    local function slider(key,root,fill,knob,value,minimum,maximum)
        local view={key=key,root=root,fill=fill,knob=knob,value=value,minimum=minimum,maximum=maximum}
        table.insert(sliderViews,view)
        local hit=Instance.new("TextButton")
        hit.Name="SliderInput"; hit.Text=""; hit.BackgroundTransparency=1
        hit.Size=UDim2.fromScale(1,1); hit.ZIndex=20; hit.Parent=n(root)
        local function update(x)
            local ratio=math.clamp((x-n(root).AbsolutePosition.X)/math.max(1,n(root).AbsoluteSize.X),0,1)
            settings[key]=math.floor(minimum+ratio*(maximum-minimum)+0.5)
            applySettings()
        end
        view.update=update
        connect(hit.InputBegan,safe(function(input)
            if input.UserInputType==Enum.UserInputType.MouseButton1 or input.UserInputType==Enum.UserInputType.Touch then
                dragging={view=view,input=input}; update(input.Position.X)
            elseif input.KeyCode==Enum.KeyCode.Left or input.KeyCode==Enum.KeyCode.Right then
                local delta=input.KeyCode==Enum.KeyCode.Right and 1 or -1
                settings[key]=math.clamp(settings[key]+delta*(key=="delay" and 100 or 1),minimum,maximum)
                changedSettings()
            end
        end))
    end
