        RaidCatalog=RaidCatalog,MainModes=MainModes,world=runtime.mainWorld})
    Theme.finish({n=n,gui=gui,nodes=nodes,legacyNodes=legacyNodes,extra=extra,runtime=runtime,baseTransparency=baseTransparency})
    EditedLayout.apply({gui=gui,n=n,baseTransparency=baseTransparency})
    runtime.helpSections=HelpSections.mount({gui=gui,bind=bind})
    MiscController.mount({runtime=runtime,nodes=nodes,gui=gui,player=player,prefix=prefix,
        readJSON=readJSON,writeJSON=writeJSON,report=report,bind=bind,switchVisual=switchVisual,
        baseTransparency=baseTransparency,opacity=function() return settings.opacity/100 end,
        Utility=MiscUtility,Overrides=MiscOverrides})
    AutoPlayController.mount({runtime=runtime,core=core,broker=broker,player=player,prefix=prefix,n=n,
        AutoPlay=AutoPlay,readJSON=readJSON,writeJSON=writeJSON,report=report,bind=bind,connect=connect,safe=safe,
        text=text,switchVisual=switchVisual,baseTransparency=baseTransparency,
        opacity=function() return settings.opacity/100 end,delay=function() return settings.delay end,
        autoHide=function() return settings.autoHide end,selected=function() return selectedName end,
        prepare=function() storage();autoLoader:prepare() end,restore=function(name) loadMacro(name) end,
        prepareMacro=prepareAutoMacro,
        ready=function() return not runtime.mainWorld.lobbyServer() and findRemote()~=nil and workspace:FindFirstChild("_UNITS")~=nil end,
        state=function()
            local started=workspace:FindFirstChild("_waves_started");local wave=workspace:FindFirstChild("_wave_num")
            return started and started.Value,wave and wave.Value
        end})
    applySettings()
    -- Reveal only after all controls, settings and adapters have initialized.
    task.defer(function()
        if runtime.alive and not (settings.autoHide and findRemote()) then runtime.show() end
    end)

    -- APP_TEST_INSERTION_POINT
    return runtime
end
return App

end)()
modules.App.start(modules)
